CREATE TABLE IF NOT EXISTS public.crm_derivation_catalog (workspace_id uuid NOT NULL REFERENCES public.workspaces(id),version integer NOT NULL,active boolean NOT NULL DEFAULT false,rules jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,version));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_derivation_catalog TO authenticated;
GRANT ALL ON public.crm_derivation_catalog TO service_role;
ALTER TABLE public.crm_derivation_catalog ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS derivation_read ON public.crm_derivation_catalog;
CREATE POLICY derivation_read ON public.crm_derivation_catalog FOR SELECT TO authenticated USING(public.is_workspace_member(workspace_id,auth.uid()));
DROP POLICY IF EXISTS derivation_manage ON public.crm_derivation_catalog;
CREATE POLICY derivation_manage ON public.crm_derivation_catalog FOR ALL TO authenticated USING(public.is_active_workspace_admin(workspace_id,auth.uid()) AND NOT public.is_read_only_view()) WITH CHECK(public.is_active_workspace_admin(workspace_id,auth.uid()) AND NOT public.is_read_only_view());
CREATE UNIQUE INDEX IF NOT EXISTS crm_derivation_active ON public.crm_derivation_catalog(workspace_id) WHERE active;
CREATE OR REPLACE FUNCTION public.crm_catalog_version_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$ BEGIN IF TG_OP='DELETE' OR NEW.rules IS DISTINCT FROM OLD.rules OR NEW.version IS DISTINCT FROM OLD.version OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN RAISE EXCEPTION 'Create a new catalog version instead of altering existing rules' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS crm_catalog_immutable ON public.crm_derivation_catalog;
CREATE TRIGGER crm_catalog_immutable BEFORE UPDATE OR DELETE ON public.crm_derivation_catalog FOR EACH ROW EXECUTE FUNCTION public.crm_catalog_version_guard();
CREATE TABLE IF NOT EXISTS public.crm_derivation_backup (run_key text NOT NULL,workspace_id uuid NOT NULL,entity text NOT NULL,record_id uuid NOT NULL,snapshot jsonb NOT NULL,captured_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(run_key,entity,record_id));
GRANT SELECT ON public.crm_derivation_backup TO authenticated;
GRANT ALL ON public.crm_derivation_backup TO service_role;
ALTER TABLE public.crm_derivation_backup ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS derivation_backup_read ON public.crm_derivation_backup;
CREATE POLICY derivation_backup_read ON public.crm_derivation_backup FOR SELECT TO authenticated USING(public.is_active_workspace_admin(workspace_id,auth.uid()) AND NOT public.is_read_only_view());
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS job_title text;
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS job_title_source text;
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS cargo_resumido text;
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS area_atuacao text;
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS nivel_hierarquico text;
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS cargo_catalog_version integer;
ALTER TABLE public.contacts ADD COLUMN IF NOT EXISTS cargo_resumido text;
ALTER TABLE public.contacts ADD COLUMN IF NOT EXISTS area_atuacao text;
ALTER TABLE public.contacts ADD COLUMN IF NOT EXISTS nivel_hierarquico text;
ALTER TABLE public.contacts ADD COLUMN IF NOT EXISTS cargo_catalog_version integer;
ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS size_description text;
COMMENT ON COLUMN public.leads.job_title IS 'Canonical editable Cargo. Explicit edits/clears take precedence over hs_raw. Legacy synchronization only while source=legacy.';
COMMENT ON COLUMN public.leads.job_title_source IS 'Internal provenance: explicit or legacy; explicit empty Cargo must never resurrect legacy.';
COMMENT ON COLUMN public.companies.size_description IS 'Employee count bands only; not legal company size. Broad ranges=Faixa abrangente; invalid/empty=NULL.';
CREATE OR REPLACE FUNCTION public.crm_normalize_title(v text) RETURNS text LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT btrim(regexp_replace(translate(lower(normalize(coalesce(v,''),NFKD)),U&'\0300\0301\0302\0303\0308\0327',''),'[^a-z0-9]+',' ','g')) $$;
CREATE OR REPLACE FUNCTION public.crm_employee_integer(v text) RETURNS bigint LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ DECLARE s text:=btrim(v); BEGIN IF s IS NULL OR s='' THEN RETURN NULL; END IF; IF s ~ '^[0-9]+$' THEN NULL; ELSIF s ~ '^[1-9][0-9]{0,2}([.,][0-9]{3})+$' AND NOT(s LIKE '%.%' AND s LIKE '%,%') THEN s:=replace(replace(s,'.',''),',',''); ELSE RETURN NULL; END IF; BEGIN RETURN s::bigint; EXCEPTION WHEN numeric_value_out_of_range THEN RETURN NULL; END; END $$;
CREATE OR REPLACE FUNCTION public.crm_employee_band(n bigint) RETURNS text LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT CASE WHEN n IS NULL OR n<0 THEN NULL WHEN n<=50 THEN '0 a 50' WHEN n<=100 THEN '51 a 100' WHEN n<=200 THEN '101 a 200' WHEN n<=500 THEN '201 a 500' WHEN n<=1000 THEN '501 a 1.000' WHEN n<=5000 THEN '1.001 a 5.000' WHEN n<=10000 THEN '5.001 a 10.000' ELSE 'Acima de 10.000' END $$;
CREATE OR REPLACE FUNCTION public.crm_size_description(v text) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ DECLARE parts text[];lo bigint;hi bigint;s text:=btrim(v); BEGIN IF s IS NULL OR s='' THEN RETURN NULL; END IF; lo:=public.crm_employee_integer(s); IF lo IS NOT NULL THEN RETURN public.crm_employee_band(lo); END IF; parts:=regexp_match(s,'^([0-9][0-9.,]*)\s*[-–—]\s*([0-9][0-9.,]*)$'); IF parts IS NULL THEN RETURN NULL; END IF; lo:=public.crm_employee_integer(parts[1]);hi:=public.crm_employee_integer(parts[2]); IF lo IS NULL OR hi IS NULL OR lo>hi THEN RETURN NULL; END IF; IF public.crm_employee_band(lo)=public.crm_employee_band(hi) THEN RETURN public.crm_employee_band(lo); END IF; RETURN 'Faixa abrangente'; END $$;
CREATE OR REPLACE FUNCTION public.crm_classify_title(v text,rules jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ DECLARE s text:=public.crm_normalize_title(v);r jsonb;hit jsonb;domains text[]:=ARRAY[]::text[];levels text[]:=ARRAY[]::text[];titles text[]:=ARRAY[]::text[];a text;l text;t text; BEGIN IF s='' THEN RETURN jsonb_build_object('title',NULL,'area',NULL,'level',NULL); END IF; FOR r IN SELECT value FROM jsonb_array_elements(rules) ORDER BY(value->>'priority')::integer LOOP IF s ~ (r->>'pattern') THEN a:=r->>'area';l:=r->>'level';t:=r->>'title'; IF a IS NOT NULL AND NOT a=ANY(domains) THEN domains:=array_append(domains,a); END IF; IF l IS NOT NULL AND NOT l=ANY(levels) THEN levels:=array_append(levels,l); END IF; IF t IS NOT NULL AND NOT t=ANY(titles) THEN titles:=array_append(titles,t); END IF; IF hit IS NULL AND t IS NOT NULL THEN hit:=r; END IF; END IF; END LOOP; IF cardinality(domains)>1 OR(s ~ '\m(socio|partner|presidente|president)\M' AND cardinality(levels)>1) OR(s ~ '\m(ceo|cto|cio|cfo|coo|chro|ciso|cdo)\M' AND cardinality(titles)>1) THEN RETURN jsonb_build_object('title','Classificação ambígua','area','Classificação ambígua','level','Classificação ambígua'); END IF; RETURN jsonb_build_object('title',coalesce(hit->>'title','Não classificado'),'area',coalesce(domains[1],'Não classificado'),'level',coalesce(levels[1],'Não classificado')); END $$;
CREATE OR REPLACE FUNCTION public.crm_derive_row() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$ DECLARE cfg record;d jsonb;raw_title text;old_raw text; BEGIN SELECT version,rules INTO cfg FROM public.crm_derivation_catalog WHERE workspace_id=NEW.workspace_id AND active; IF NOT FOUND THEN RETURN NEW; END IF; IF TG_TABLE_NAME='companies' THEN NEW.size_description:=public.crm_size_description(NEW.size); RETURN NEW; END IF; IF TG_TABLE_NAME='leads' THEN raw_title:=coalesce(nullif(NEW.hs_raw#>>'{properties,hs_contact_job_title}',''),nullif(NEW.hs_raw#>>'{properties,cargo_formatado}','')); IF TG_OP='INSERT' THEN NEW.job_title_source:=CASE WHEN NEW.job_title IS NOT NULL THEN 'explicit' ELSE 'legacy' END; IF NEW.job_title IS NULL THEN NEW.job_title:=raw_title; END IF; ELSE old_raw:=coalesce(nullif(OLD.hs_raw#>>'{properties,hs_contact_job_title}',''),nullif(OLD.hs_raw#>>'{properties,cargo_formatado}','')); IF NEW.job_title IS DISTINCT FROM OLD.job_title THEN NEW.job_title_source:='explicit'; ELSE NEW.job_title_source:=OLD.job_title_source; IF OLD.job_title_source IS NULL OR(OLD.job_title_source='legacy' AND raw_title IS DISTINCT FROM old_raw) THEN NEW.job_title:=raw_title;NEW.job_title_source:='legacy'; END IF; END IF; END IF; END IF; d:=public.crm_classify_title(NEW.job_title,cfg.rules);NEW.cargo_resumido:=d->>'title';NEW.area_atuacao:=d->>'area';NEW.nivel_hierarquico:=d->>'level';NEW.cargo_catalog_version:=cfg.version;RETURN NEW; END $$;
DROP TRIGGER IF EXISTS zz_crm_derive ON public.contacts;
CREATE TRIGGER zz_crm_derive BEFORE INSERT OR UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION public.crm_derive_row();
DROP TRIGGER IF EXISTS zz_crm_derive ON public.leads;
CREATE TRIGGER zz_crm_derive BEFORE INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.crm_derive_row();
DROP TRIGGER IF EXISTS zz_crm_derive ON public.companies;
CREATE TRIGGER zz_crm_derive BEFORE INSERT OR UPDATE ON public.companies FOR EACH ROW EXECUTE FUNCTION public.crm_derive_row();
CREATE OR REPLACE FUNCTION public.crm_is_derivation_backfill(old_row jsonb,new_row jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT current_user NOT IN('authenticated','anon','service_role') AND auth.uid() IS NULL AND coalesce(current_setting('app.crm_derivation_backfill',true),'')='wk-2026-10-16' AND old_row->>'workspace_id'='184b9435-0a9b-4334-9e89-8854dc883f5d' AND new_row->>'workspace_id'=old_row->>'workspace_id' AND(old_row-ARRAY['cargo_resumido','area_atuacao','nivel_hierarquico','cargo_catalog_version','job_title','job_title_source','size_description','updated_at'])=(new_row-ARRAY['cargo_resumido','area_atuacao','nivel_hierarquico','cargo_catalog_version','job_title','job_title_source','size_description','updated_at']) $$;
DO $patch$ DECLARE f record;body text; BEGIN FOR f IN SELECT p.oid,p.proname,pg_get_functiondef(p.oid) def FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN('set_updated_at','log_property_changes','log_audit_event','enqueue_workflow_event') LOOP body:=f.def; IF position('crm_is_derivation_backfill' IN body)=0 THEN body:=regexp_replace(body,'\m[Bb][Ee][Gg][Ii][Nn]\M',E'BEGIN\n IF TG_OP = ''UPDATE'' AND public.crm_is_derivation_backfill(to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW; END IF;');EXECUTE body; END IF; END LOOP; END $patch$;
CREATE INDEX IF NOT EXISTS contacts_cargo_derived_filter ON public.contacts(workspace_id,area_atuacao,nivel_hierarquico,cargo_resumido) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS leads_cargo_derived_filter ON public.leads(workspace_id,area_atuacao,nivel_hierarquico,cargo_resumido) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS companies_size_description_filter ON public.companies(workspace_id,size_description) WHERE deleted_at IS NULL;